#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

/*
 * Reimplementation of prog25_balanced_multitype.
 *
 * Behaviour:
 *   - If no argument is supplied, prints "BALANCED".
 *   - If an argument is supplied, checks whether the string contains
 *     balanced parentheses, square brackets and curly braces. All other
 *     characters are ignored.
 *   - Prints "BALANCED" if the brackets are properly nested and matched,
 *     otherwise prints "UNBALANCED".
 */

static bool is_balanced(const char *s)
{
    size_t len = strlen(s);
    char *stack = malloc(len);
    if (!stack) {
        return false; // allocation failure -> treat as unbalanced
    }
    size_t top = 0;
    bool ok = true;
    for (size_t i = 0; i < len && ok; ++i) {
        char c = s[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack[top++] = c; // push
                break;
            case ')':
            case ']':
            case '}': {
                if (top == 0) { // nothing to pop
                    ok = false;
                    break;
                }
                char open = stack[--top]; // pop
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    ok = false;
                }
                break;
            }
            default:
                // ignore other characters
                break;
        }
    }
    ok = ok && (top == 0);
    free(stack);
    return ok;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }
    if (is_balanced(argv[1]))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
